{
  "definition_simple": "后设指的是对某一事物本身进行的反思、分析或超越，通常用于描述关于某个对象或系统的更高层次的概念。",
  "definition_standard": "后设（meta-）是一个前缀或修饰语，表示对某事物本身的性质、结构或认知的再思考或再分析，例如后设认知（metacognition）指对自身认知过程的认知。",
  "pos": "名词",
  "semantic_class": "abstract",
  "sentences": [
    {"sentence": "后设这个词听起来很专业。", "tier": "T1"},
    {"sentence": "你知道什么是后设认知吗？", "tier": "T1"},
    {"sentence": "后设认知是心理学中的一个重要概念。", "tier": "T2"},
    {"sentence": "这篇论文分析了后设叙事的结构。", "tier": "T2"},
    {"sentence": "后设理论可以帮助我们检验其他理论的假设。", "tier": "T3"},
    {"sentence": "他的后设意识非常敏锐，总能反思自己的思考过程。", "tier": "T3"},
    {"sentence": "在语言学中，后设语言是用来描述自然语言的工具。", "tier": "T4"},
    {"sentence": "后设编码是一种涉及代码自省的高级编程技巧。", "tier": "T4"},
    {"sentence": "后设批判的视角让我们能剖析文本背后的意识形态。", "tier": "T5"},
    {"sentence": "后设本体论质疑现实的基本范畴，认为它们本身需要被重新定义。", "tier": "T6"}
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "后舍",
      "explanation": "“后舍”与“后设”同音（hòu shè），指后面的房屋，学习者可能因听写混淆而误写为“后舍”。"
    },
    {
      "word": "后摄",
      "explanation": "“后摄”与“后设”同音（hòu shè），是摄影术语（后景或后置摄像头），音同导致听力误解。"
    },
    {
      "word": "后社",
      "explanation": "“后社”与“后设”同音（hòu shè），指后部的社团或村庄，学术语境中可能被听错。"
    }
  ],
  "primary_collocate": "认知",
  "collocation_distractors": [
    {
      "word": "情绪",
      "explanation": "“后设情绪”并非标准术语，尽管情绪与认知相关，但“后设”通常不与“情绪”直接搭配。"
    },
    {
      "word": "行为",
      "explanation": "“后设行为”很少使用，因为“后设”主要修饰认知、语言等抽象系统，不修饰具体行为。"
    },
    {
      "word": "经验",
      "explanation": "“后设经验”不是固定搭配，虽然经验可被反思，但学术上常用“元经验”而非“后设经验”。"
    }
  ],
  "collocation_wrong_collocate": {
    "word": "系统",
    "explanation": "“后设系统”从字面看合理（如元系统），但实际学术文献中多用“元系统”或“后设理论”，极少单独说“后设系统”。"
  },
  "cloze_distractors": [
    {
      "word": "哲学",
      "explanation": "虽然哲学也讨论认知，但后设认知属于心理学范畴，填入“哲学”会导致学科错配。"
    },
    {
      "word": "历史",
      "explanation": "历史学科与认知机制完全无关，填入后句子不合理。"
    },
    {
      "word": "技术",
      "explanation": "技术不是学科，填入后语义不通。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "他后设了这个问题。",
      "reason": "“后设”在中文中不能用作动词，这里错误地将其当作及物动词使用。"
    },
    {
      "sentence": "这个后设很漂亮。",
      "reason": "“后设”是抽象概念，不能像具体物体那样被描述为“漂亮”，犯了语义类别错误。"
    },
    {
      "sentence": "后设是一种水果。",
      "reason": "“后设”是学术抽象名词，完全不属于水果范畴，属于范畴错误。"
    }
  ],
  "spot_incorrect": {
    "sentence": "后设认知是一种高级的数学技能。",
    "error_description": "后设认知属于认知心理学领域，与数学技能无关，用“数学”是错误领域。",
    "corrected": "后设认知是一种高级的认知技能。"
  },
  "word_family_forms": [
    {"form": "后设性", "pos": "名词"},
    {"form": "后设化", "pos": "动词"}
  ],
  "word_family_fake_forms": [
    {
      "form": "后设者",
      "explanation": "虽然“者”是常见后缀（如“工作者”），但“后设”不指代人，不存在“后设者”这个派生词。"
    },
    {
      "form": "后设度",
      "explanation": "“度”可表示程度（如“长度”），但“后设度”没有实际意义，是虚构的抽象名词。"
    },
    {
      "form": "后设式",
      "explanation": "“式”表示方式或样式（如“模式”），但“后设式”在中文中并无使用，是伪造的形容词形式。"
    }
  ],
